// ===== 바꿀 값은 이 노드에만 있습니다 =====
const cfg = {
  githubOwner: 'YOUR-GITHUB-ID',
  githubRepo: 'invest-news-site',
  githubBranch: 'main',
  siteUrl: 'https://invest-news-site.vercel.app',
  supabaseUrl: 'https://YOUR-PROJECT.supabase.co',
  vaultRepo: 'invest-vault', // 비우면 옵시디안 노트를 만들지 않음
  vaultBranch: 'main',
  discordWebhookUrl: '', // #브리핑 웹훅. 비우면 알림 없음
  geminiModel: 'gemini-3.8-flash',
  fallbackModel: 'gemini-flash-lite-latest',
  embeddingModel: 'gemini-embedding-001',
  embedDim: 768,
  maxStories: 25, // 이번 주 주요 뉴스 후보 수
  maxFilings: 12, // 이번 주 주요 공시 후보 수
};
// 이번 주 = 오늘(한국 시간) 기준 월~일, 다음 주 = 그다음 월~일
const now = new Date();
const kstMs = now.getTime() + 9 * 3600_000;
const d = new Date(kstMs);
const dow = (d.getUTCDay() + 6) % 7; // 월=0 … 일=6
const day = (off) => new Date(kstMs + off * 86400_000).toISOString().slice(0, 10);
const mon = day(-dow), sun = day(6 - dow), nextMon = day(7 - dow), nextSun = day(13 - dow);
// ISO 주차
const t = new Date(Date.UTC(+mon.slice(0, 4), +mon.slice(5, 7) - 1, +mon.slice(8, 10) + 3));
const y = t.getUTCFullYear();
const week = Math.ceil(((t - Date.UTC(y, 0, 1)) / 86400000 + 1) / 7); // t는 그 주의 목요일
const wk = `${y}-W${String(week).padStart(2, '0')}`;
return [{
  json: {
    ...cfg,
    nowIso: now.toISOString(),
    mon, sun, nextMon, nextSun,
    sinceIso: new Date(Date.parse(`${mon}T00:00:00+09:00`)).toISOString(),
    week: wk,
    title: `${y}년 ${week}주차 주간 리포트 (${mon.slice(5).replace('-', '.')}~${sun.slice(5).replace('-', '.')})`,
  },
}];

// 한 주치 자료를 모아 번호(W1…)를 붙이고 Gemini 요청을 만듭니다.
const c = $('설정').first().json;
const rows = (n) => $(n).all().map((i) => i.json).filter((r) => r && Object.keys(r).length);
const arts = rows('주간 기사 조회');
const inds = rows('지표 조회');
const events = rows('다음 주 일정 조회');
const watch = (($('관심 종목 조회').first().json || {}).watchlist) || [];
const research = rows('주간 리서치 조회');
const day = (iso) => new Date(Date.parse(iso) + 9 * 3600_000).toISOString().slice(0, 10);

// 사건마다 대표 1건 (신뢰도·중요도 높은 것), 뉴스와 공시 따로
function reps(list, n) {
  const m = new Map();
  for (const a of list) {
    const k = a.story_key || `a-${a.id}`;
    const cur = m.get(k);
    if (!cur || (a.importance || 0) > (cur.importance || 0)) m.set(k, a);
  }
  return [...m.values()].sort((a, b) => (b.importance || 0) - (a.importance || 0)).slice(0, n);
}
const news = reps(arts.filter((a) => a.tier !== 'T1'), c.maxStories);
const filings = reps(arts.filter((a) => a.tier === 'T1'), c.maxFilings);

const sources = [];
const add = (a, kind) => { const id = `W${sources.length + 1}`; sources.push({ id, kind, title: a.title_ko || a.title, source: a.source, url: a.url, date: day(a.published_at), market: a.market, sentiment: a.sentiment || '중립', importance: a.importance || 0, tickers: a.tickers || [] }); return id; };
filings.forEach((a) => add(a, 'filing'));
news.forEach((a) => add(a, 'news'));

// 관심 종목별 한 주 통계
const has = (a, w) => (a.tickers || []).some((t) => t.code === w.code && t.market === w.market);
const watchStats = watch.map((w) => {
  const mine = arts.filter((a) => has(a, w));
  const cnt = (s) => mine.filter((a) => a.sentiment === s).length;
  return { market: w.market, code: w.code, name: w.name, total: mine.length, filings: mine.filter((a) => a.tier === 'T1').length, up: cnt('호재'), down: cnt('악재'), refs: sources.filter((s) => s.tickers.some((t) => t.code === w.code && t.market === w.market)).slice(0, 4).map((s) => s.id) };
});

// 지표: 최근 값과 1주 전 값 (일간 지표만 1주 비교, 월간 지표는 이번 주 발표된 경우 표시)
const num = (v) => (v === null || v === undefined ? '-' : Number(v).toLocaleString('en-US', { maximumFractionDigits: Math.abs(v) < 10 ? 4 : 2 }));
const indLines = inds.map((i) => {
  const h = Array.isArray(i.history) ? i.history : [];
  const daily = /^\d{4}-\d{2}-\d{2}$/.test(String(i.latest_date || ''));
  let line = `${i.name}: ${num(i.latest_value)}${i.unit === '%' ? '%' : ` ${i.unit}`} (${i.latest_date})`;
  if (daily) {
    const prev = [...h].reverse().find((p) => p[0] < c.mon);
    if (prev && i.latest_value !== null) line += `, 1주 전 ${num(prev[1])} → ${(i.latest_value - prev[1] >= 0 ? '+' : '')}${num(Math.round((i.latest_value - prev[1]) * 10000) / 10000)}`;
  } else if (String(i.updated_at || '') >= c.sinceIso && i.prev_value !== null) {
    line += `, 이전 발표 ${num(i.prev_value)}`;
  }
  return { key: i.series_key, market: i.market, line };
});

const evLines = events.map((e) => `${e.event_date} ${e.event_time || ''} [${e.market === 'US' ? '미국' : '한국'}] ${e.name}${'★'.repeat(e.importance || 1)}`.replace(/\s+/g, ' ').trim());
const line = (s) => `[${s.id}] ${s.date} ${s.source} · ${s.title} (중요도 ${s.importance}, ${s.sentiment})`;
const pack = [
  `기간: ${c.mon} ~ ${c.sun}`,
  '', '## 이번 주 주요 공시 (W)', ...(sources.filter((s) => s.kind === 'filing').map(line)), sources.some((s) => s.kind === 'filing') ? '' : '(없음)',
  '', '## 이번 주 주요 뉴스 (W)', ...(sources.filter((s) => s.kind === 'news').map(line)), sources.some((s) => s.kind === 'news') ? '' : '(없음)',
  '', '## 관심 종목 이번 주 통계', ...(watchStats.length ? watchStats.map((w) => `${w.name}(${w.code}): 기사 ${w.total}건, 공시 ${w.filings}건, 호재 ${w.up} · 악재 ${w.down}, 관련 번호 ${w.refs.join(', ') || '없음'}`) : ['(관심 종목 없음)']),
  '', '## 지표 (최근 값, 1주 비교)', ...indLines.map((l) => l.line),
  '', `## 다음 주 일정 (${c.nextMon} ~ ${c.nextSun}, 한국 시간)`, ...(evLines.length ? evLines : ['(없음)']),
  '', '## 이번 주 리서치', ...(research.length ? research.map((r) => `- ${r.title}`) : ['(없음)']),
].join('\n');

const text = `너는 한국 개인 투자자를 위한 주간 시장 리포트 편집자다. 아래 자료만 근거로 지난 한 주를 정리하고 다음 주를 준비하는 리포트를 한국어로 써라.

규칙
- 자료에 없는 사실을 만들지 마라. 근거는 refs에 번호(W1 등)로만 달고 URL은 쓰지 마라.
- 매수·매도 권유, 목표주가, 가격 예측은 쓰지 마라. "체크포인트"는 확인할 일정·지표·공시로만.
- 지표는 숫자 변화를 그대로 전하고 해석은 짧게.

출력: JSON 하나만.
{"headline": "이번 주를 한 문장으로",
 "summary": ["**핵심어**: 문장" 3~5줄],
 "market": [{"text": "이번 주 시장 흐름 1~2문장", "refs": ["W3"]}] 3~5개,
 "watch": [{"name": "관심 종목 이름", "text": "이번 주 그 종목 소식 1~2문장 (없으면 '특별한 소식 없음')", "refs": ["W1"]}],
 "data": ["지표·시장 심리 변화 한 문장"] 2~4개,
 "nextWeek": ["다음 주 체크포인트 (날짜 포함)"] 3~5개}

${pack}`;

return [{
  json: {
    sources, watchStats, indLines, events: events.map((e) => ({ date: e.event_date, time: e.event_time, market: e.market, name: e.name, importance: e.importance })),
    research: research.map((r) => ({ title: r.title, key: r.report_key })),
    stats: { articles: arts.length, filings: arts.filter((a) => a.tier === 'T1').length, research: research.length },
    body: { contents: [{ role: 'user', parts: [{ text }] }], generationConfig: { responseMimeType: 'application/json', maxOutputTokens: 8192, thinkingConfig: { thinkingLevel: 'low' } } },
  },
}];

// Gemini 응답에서 글자만 꺼내고, JSON이면 읽어 줍니다.
function geminiText(j) {
  const parts = ((((j || {}).candidates || [])[0] || {}).content || {}).parts || [];
  return parts.filter((p) => !p.thought).map((p) => p.text || '').join('');
}
function parseJson(t) {
  t = String(t || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  try { return JSON.parse(t); } catch (e) {}
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(t.slice(a, b + 1)); } catch (e) {} }
  return null;
}
// 주간 리포트 완성. Gemini가 실패하면 숫자·목록만으로 된 리포트를 대신 만듭니다.
const c = $('설정').first().json;
const P = $('자료 정리').first().json;
const { sources } = P;
const ids = new Set(sources.map((s) => s.id));
const byId = Object.fromEntries(sources.map((s) => [s.id, s]));
const clean = (s) => String(s || '').replace(/https?:\/\/\S+/g, '').trim();
const refs = (r) => (Array.isArray(r) ? r.map(String).filter((x) => ids.has(x)).slice(0, 5) : []);

let o = null;
for (const it of $input.all()) { o = parseJson(geminiText(it.json)); if (o && Array.isArray(o.summary)) break; o = null; }
const ai = !!o;
let rep;
if (ai) {
  rep = {
    headline: clean(o.headline),
    summary: (o.summary || []).map(clean).filter(Boolean).slice(0, 5),
    market: (o.market || []).map((x) => ({ text: clean(x.text), refs: refs(x.refs) })).filter((x) => x.text).slice(0, 6),
    watch: (o.watch || []).map((x) => ({ name: clean(x.name), text: clean(x.text), refs: refs(x.refs) })).filter((x) => x.name && x.text),
    data: (o.data || []).map(clean).filter(Boolean).slice(0, 5),
    nextWeek: (o.nextWeek || []).map(clean).filter(Boolean).slice(0, 6),
  };
} else {
  const top = sources.filter((s) => s.kind === 'news').slice(0, 5);
  rep = {
    headline: '이번 주 주요 뉴스와 지표 정리 (AI 요약 없이 자동 정리)',
    summary: top.slice(0, 3).map((s) => `**${s.source}**: ${s.title}`),
    market: top.map((s) => ({ text: s.title, refs: [s.id] })),
    watch: P.watchStats.map((w) => ({ name: w.name, text: `기사 ${w.total}건, 공시 ${w.filings}건 (호재 ${w.up} · 악재 ${w.down})`, refs: w.refs })),
    data: P.indLines.slice(0, 6).map((l) => l.line),
    nextWeek: P.events.filter((e) => (e.importance || 1) >= 2).slice(0, 6).map((e) => `${e.date.slice(5).replace('-', '.')} ${e.time || ''} ${e.name}`.replace(/\s+/g, ' ')),
  };
}
const used = new Set([...rep.market, ...rep.watch].flatMap((x) => x.refs));
const usedSources = sources.filter((s) => used.has(s.id)).map(({ tickers, importance, ...s }) => s);

function b64(str) {
  const by = [];
  for (let i = 0; i < str.length; i++) {
    let cp = str.charCodeAt(i);
    if (cp >= 0xd800 && cp < 0xdc00 && i + 1 < str.length) { const lo = str.charCodeAt(i + 1); if (lo >= 0xdc00 && lo < 0xe000) { cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00); i++; } }
    if (cp < 0x80) by.push(cp); else if (cp < 0x800) by.push(0xc0 | (cp >> 6), 0x80 | (cp & 63)); else if (cp < 0x10000) by.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63)); else by.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 63), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
  }
  const T = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let out = '';
  for (let i = 0; i < by.length; i += 3) { const n = (by[i] << 16) | ((by[i + 1] || 0) << 8) | (by[i + 2] || 0); out += T[(n >> 18) & 63] + T[(n >> 12) & 63] + (i + 1 < by.length ? T[(n >> 6) & 63] : '=') + (i + 2 < by.length ? T[n & 63] : '='); }
  return out;
}

// ---------- 사이트 파일 ----------
const site = [
  '---',
  `title: ${JSON.stringify(c.title)}`,
  `week: ${JSON.stringify(c.week)}`,
  `range: ${JSON.stringify(`${c.mon} ~ ${c.sun}`)}`,
  `createdAt: ${JSON.stringify(c.nowIso)}`,
  `ai: ${ai}`,
  `report: ${JSON.stringify(rep)}`,
  `events: ${JSON.stringify(P.events)}`,
  `stats: ${JSON.stringify(P.stats)}`,
  `research: ${JSON.stringify(P.research)}`,
  usedSources.length ? 'sources:' : 'sources: []',
  ...usedSources.map((s) => `  - ${JSON.stringify(s)}`),
  '---',
  '',
].join('\n');

// ---------- 옵시디안 ----------
const esc = (t) => String(t).replace(/[[\]]/g, (m) => '\\' + m);
const link = (r) => { const s = byId[r]; return s && s.url ? `[${r}](${s.url})` : r; };
const withRefs = (x) => `${x.text}${x.refs.length ? ' ' + x.refs.map(link).join(' ') : ''}`;
const sec = (t, lines) => (lines.length ? [`## ${t}`, ...lines, ''] : []);
const vault = [
  '---',
  `주차: ${JSON.stringify(c.week)}`,
  `기간: ${JSON.stringify(`${c.mon} ~ ${c.sun}`)}`,
  `AI해석: ${ai}`,
  `사이트: ${JSON.stringify(`${c.siteUrl}/weekly/${c.week}`)}`,
  'tags: ["주간리포트"]',
  '---',
  '',
  `# ${c.title}`,
  '',
  rep.headline ? `> ${rep.headline}` : '',
  '',
  ...sec(ai ? '핵심 (AI 요약)' : '핵심', rep.summary.map((l) => `- ${l}`)),
  ...sec('이번 주 시장 흐름', rep.market.map((x) => `- ${withRefs(x)}`)),
  ...sec('관심 종목', rep.watch.map((x) => `- **${x.name}**: ${withRefs(x)}`)),
  ...sec('지표·시장 심리', rep.data.map((l) => `- ${l}`)),
  ...sec('다음 주 체크포인트', rep.nextWeek.map((l) => `- [ ] ${l}`)),
  ...sec('출처', usedSources.map((s) => `- ${s.id} ${s.date} ${s.source} · ${s.url ? `[${esc(s.title)}](${s.url})` : s.title}`)),
  `관련: [[${c.sun} 시장]]`,
  '',
].join('\n');

// ---------- Discord ----------
const discord = [
  `🗓️ **${c.title}**`,
  rep.headline ? `_${rep.headline}_` : '',
  ...rep.summary.map((l) => `• ${l}`),
  '',
  rep.nextWeek.length ? `**다음 주 체크포인트**\n${rep.nextWeek.slice(0, 5).map((l) => `• ${l}`).join('\n')}` : '',
  '',
  `전체 리포트: ${c.siteUrl}/weekly/${c.week} (1~2분 뒤 열립니다)`,
].filter((x, i, a) => x !== '' || a[i - 1] !== '').join('\n').slice(0, 1990);

const kbText = [rep.headline, ...rep.summary, ...rep.market.map((x) => x.text), ...rep.watch.map((x) => `${x.name}: ${x.text}`), ...rep.data, ...rep.nextWeek.map((l) => `다음 주: ${l}`)].filter(Boolean).join('\n');
return [{
  json: {
    ai,
    sitePath: `src/content/weekly/${c.week}.md`,
    siteContent: b64(site),
    vaultPath: `자동/주간/${c.week} 주간 리포트.md`,
    vaultContent: b64(vault),
    reportRows: [{ report_key: `weekly:${c.week}`, kind: 'weekly', title: c.title, body: JSON.stringify(rep), tickers: [], created_at: c.nowIso }],
    kbChunks: [{ chunk_key: `weekly:${c.week}`, kind: 'weekly', is_ai: true, tier: null, source_grade: null, market: null, tickers: [], source: '주간 리포트', url: `${c.siteUrl}/weekly/${c.week}`, published_at: c.nowIso, content: `${c.title}\n${kbText}`.slice(0, 4000) }],
    discord: { username: '투자 뉴스 브리프 · 주간', content: discord },
    commitMessage: `weekly: ${c.week}${ai ? '' : ' (AI 요약 없음)'}`,
  },
}];

const c = $('설정').first().json;
const chunks = $('리포트 완성').first().json.kbChunks || [];
if (!chunks.length) return [];
return [{ json: { chunks, body: { requests: chunks.map((k) => ({ model: `models/${c.embeddingModel}`, content: { parts: [{ text: k.content }] }, taskType: 'RETRIEVAL_DOCUMENT', outputDimensionality: c.embedDim })) } } }];

// 임베딩 결과를 조각과 짝지어 저장할 행을 만듭니다. 768차원으로 줄인 벡터는 길이를 1로 맞춥니다.
const c = $('설정').first().json;
const reqs = $('지식베이스 준비').all();
function paired(item) {
  const p = item.pairedItem;
  if (Array.isArray(p)) return p[0] ? p[0].item : 0;
  return p && typeof p.item === 'number' ? p.item : 0;
}
const rows = [];
for (const it of $input.all()) {
  const req = reqs[paired(it)];
  const embs = (it.json && it.json.embeddings) || [];
  if (!req || embs.length !== req.json.chunks.length) throw new Error('임베딩 결과 개수가 요청과 다릅니다');
  req.json.chunks.forEach((k, i) => {
    const v = embs[i].values || [];
    if (v.length !== c.embedDim) throw new Error(`임베딩 크기 ${v.length} ≠ embedDim ${c.embedDim}`);
    const norm = Math.sqrt(v.reduce((s, x) => s + x * x, 0)) || 1;
    rows.push({ ...k, embedding: v.map((x) => Math.round((x / norm) * 1e6) / 1e6) });
  });
}
if (!rows.length) return [];
return [{ json: { rows } }];
